escenas.animacion:
const W=A.W,H=A.H,acc=A.accent;
const kP=A.k('pórtico',1.0), kCien=A.k('cien',1.667), kC=A.k('cobra',3.667), kSin=A.k('sin',4.0), kF=A.k('frenes.',4.667);
A.bg('#0b1430','#04070f',true);
const VX=540,VY=520;
const PX=(xw,z)=>VX+xw/z, PY=(yw,z)=>VY+(600-yw)/z;
const shake = t>kC && t<kC+0.35 ? 10*(1-(t-kC)/0.35) : 0;
A.with(()=>{
// suelo
ctx.save();
ctx.beginPath();ctx.rect(0,VY-10,W,1140-VY+10);ctx.clip();
let g=ctx.createLinearGradient(0,VY,0,1140);g.addColorStop(0,'#0d1838');g.addColorStop(1,'#060a16');
ctx.fillStyle=g;ctx.fillRect(0,VY,W,1140-VY);
// pista
const zN=40,zF=0.95;
ctx.beginPath();ctx.moveTo(PX(-480,zN),PY(0,zN));ctx.lineTo(PX(480,zN),PY(0,zN));ctx.lineTo(PX(480,zF),PY(0,zF));ctx.lineTo(PX(-480,zF),PY(0,zF));ctx.closePath();
ctx.fillStyle='#141c33';ctx.fill();
// bordes
A.line([[PX(-480,zN),PY(0,zN)],[PX(-480,zF),PY(0,zF)]],{stroke:'#ffffff',lw:6,alpha:0.85});
A.line([[PX(480,zN),PY(0,zN)],[PX(480,zF),PY(0,zF)]],{stroke:'#ffffff',lw:6,alpha:0.85});
// segmentos centrales en movimiento
const V=4;
for(let i=0;i<16;i++){
  let z=zF+(((i*2.2-V*t)%35.2)+35.2)%35.2;
  let z2=z+0.9;
  ctx.beginPath();
  ctx.moveTo(PX(-14,z),PY(0,z));ctx.lineTo(PX(14,z),PY(0,z));ctx.lineTo(PX(14,z2),PY(0,z2));ctx.lineTo(PX(-14,z2),PY(0,z2));ctx.closePath();
  ctx.fillStyle=acc;ctx.globalAlpha=0.9;ctx.fill();ctx.globalAlpha=1;
}
// estelas de velocidad
A.particles(26,7,(i,rnd)=>{
  const side=rnd()<0.5?-1:1; const ang=side*(0.35+rnd()*0.9);
  const ph=((rnd()+t*1.6)%1);
  const r1=A.lerp(120,950,ph*ph), r2=r1+60+ph*220;
  const dx=Math.sin(ang), dy=Math.cos(ang)*0.55;
  A.line([[VX+dx*r1,VY+dy*r1],[VX+dx*r2,VY+dy*r2]],{stroke:'#cfe0ff',lw:2+ph*3,alpha:0.5*ph});
});
ctx.restore();

// pórtico
const zc=1.25;
const zg=zc+V*(kC-t);
const gA=A.p(kP-0.05,0.5,'softInOut');
const drawGantry=()=>{
  if(zg<0.32||gA<=0)return;
  ctx.save();ctx.globalAlpha=gA*A.clamp((zg-0.32)/0.3);
  const lw=Math.max(3,36/zg);
  ctx.lineCap='round';
  ctx.strokeStyle='#e9eef8';ctx.lineWidth=lw;
  [-560,560].forEach(xw=>{ctx.beginPath();ctx.moveTo(PX(xw,zg),PY(0,zg));ctx.lineTo(PX(xw,zg),PY(800,zg));ctx.stroke();});
  // viga
  const bx1=PX(-600,zg),bx2=PX(600,zg),by1=PY(820,zg),by2=PY(720,zg);
  A.rect(bx1,by1,bx2-bx1,by2-by1,{fill:'#1c2850',stroke:'#e9eef8',lw:Math.max(2,10/zg),r:4/zg});
  for(let k=0;k<6;k++){const xx=A.lerp(bx1,bx2,(k+0.5)/6);ctx.strokeStyle='rgba(233,238,248,0.35)';ctx.lineWidth=Math.max(1,4/zg);ctx.beginPath();ctx.moveTo(xx-20/zg,by2);ctx.lineTo(xx+20/zg,by1);ctx.stroke();}
  // antena y cámara
  A.rect(PX(-45,zg),PY(720,zg),90/zg,55/zg,{fill:acc,r:6/zg});
  A.rect(PX(260,zg),PY(720,zg),70/zg,40/zg,{fill:'#e9eef8',r:6/zg});
  if(zg<6) A.circle(PX(0,zg),PY(690,zg),12/zg,{fill:'#fff',glow:20,alpha:0.6+0.4*Math.sin(t*20)});
  ctx.restore();
};
// haz de radio
const beam=()=>{
  const bp=A.p(kC-0.55,0.3,'softInOut')*(1-A.p(kC+0.35,0.4,'softInOut'));
  if(bp<=0||zg<0.32)return;
  const ax=PX(0,zg),ay=PY(665,zg);
  ctx.save();ctx.globalAlpha=0.45*bp;
  const gr=ctx.createLinearGradient(0,ay,0,820);gr.addColorStop(0,acc);gr.addColorStop(1,'rgba(255,212,0,0)');
  ctx.fillStyle=gr;ctx.beginPath();ctx.moveTo(ax-10,ay);ctx.lineTo(ax+10,ay);ctx.lineTo(ax+90,830);ctx.lineTo(ax-90,830);ctx.closePath();ctx.fill();
  ctx.restore();
};

// auto
const sway=Math.sin(t*3.1)*4;
const drawCar=()=>{
  const cx=540+sway, gy=1000;
  ctx.save();ctx.globalAlpha=0.5;ctx.fillStyle='#000';ctx.beginPath();ctx.ellipse(cx,gy+8,190,20,0,0,Math.PI*2);ctx.fill();ctx.restore();
  A.rect(cx-150,gy-40,48,48,{fill:'#0a0d16',r:10});
  A.rect(cx+102,gy-40,48,48,{fill:'#0a0d16',r:10});
  // cabina
  A.lib.inkPath(ctx,[[cx-118,790],[cx+118,790],[cx+150,875],[cx-150,875]],{closed:true,fill:'#2a3768',color:'#e9eef8',width:5});
  A.lib.inkPath(ctx,[[cx-100,805],[cx+100,805],[cx+125,865],[cx-125,865]],{closed:true,fill:'#0e1630',color:'#9fb4e6',width:3});
  // TAG visible por el vidrio
  const tagHot=A.p(kC-0.5,0.25)*(1-A.p(kC+0.6,0.5));
  A.rect(cx-22,812,44,24,{fill:acc,r:4,glow:tagHot*30});
  // carrocería
  A.rect(cx-172,870,344,118,{fill:'#34447f',stroke:'#e9eef8',lw:5,r:24});
  A.lib.hatch(ctx,[[cx-168,950],[cx+168,950],[cx+168,984],[cx-168,984]],{angle:0.6,spacing:9,width:1.5,color:'rgba(233,238,248,0.25)'});
  // luces traseras (apagadas: no frena)
  A.rect(cx-162,892,64,24,{fill:'#7a1020',r:6});
  A.rect(cx+98,892,64,24,{fill:'#7a1020',r:6});
  // patente
  A.rect(cx-62,915,124,40,{fill:'#f4f6fb',r:6});
  A.text('PRTC·42',cx,936,{size:26,color:'#111',weight:'800',align:'center'});
};

beam();
if(zg>zc){drawGantry();drawCar();}else{drawCar();drawGantry();}

// impacto del cobro
if(t>kC){
  A.rings(540+sway,824,kC,{count:3,speed:520,gap:0.12,maxR:380,color:acc,lw:6});
  const s=A.pop(kC,0.45);
  const rise=A.p(kC,1.2,'softLand');
  A.label('$  COBRADO',540,A.lerp(720,690,rise),{size:62,bg:acc,color:'#0b1430',scale:s});
}
},{x:540,y:800,shake});
A.flash(kC,0.18,0.35);

// velocímetro
const gIn=A.p(0.05,0.6,'snapSettle');
const v=100*A.p(0.15,kCien+0.3-0.15,'glide');
const gx=540,gy=1645,R=180;
A.with(()=>{
  ctx.save();ctx.lineCap='round';
  ctx.strokeStyle='rgba(233,238,248,0.18)';ctx.lineWidth=22;ctx.beginPath();ctx.arc(gx,gy,R,Math.PI,2*Math.PI);ctx.stroke();
  const frac=v/120;
  ctx.strokeStyle=acc;ctx.shadowColor=acc;ctx.shadowBlur=t>kF?30:12;ctx.lineWidth=22;ctx.beginPath();ctx.arc(gx,gy,R,Math.PI,Math.PI+Math.PI*frac);ctx.stroke();
  ctx.shadowBlur=0;
  for(let i=0;i<=12;i++){const a=Math.PI+Math.PI*i/12;const r1=R-30,r2=R-(i%2?42:54);ctx.strokeStyle='#e9eef8';ctx.lineWidth=i%2?2:4;ctx.beginPath();ctx.moveTo(gx+Math.cos(a)*r1,gy+Math.sin(a)*r1);ctx.lineTo(gx+Math.cos(a)*r2,gy+Math.sin(a)*r2);ctx.stroke();}
  const jit=t>kCien+0.3?Math.sin(t*23)*0.012:0;
  const na=Math.PI+Math.PI*frac+jit;
  ctx.strokeStyle='#ffffff';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(gx,gy);ctx.lineTo(gx+Math.cos(na)*(R-48),gy+Math.sin(na)*(R-48));ctx.stroke();
  ctx.restore();
  A.circle(gx,gy,14,{fill:'#fff'});
  const ns=t>kCien?A.pop(kCien+0.25,0.45):1;
  A.with(()=>{A.text(A.counter(0,100,v/100,0),gx,gy-62,{size:96,color:'#fff',weight:'900',align:'center'});},{x:gx,y:gy-80,scale:ns});
  A.text('km/h',gx,gy+44,{size:34,color:'#9fb4e6',weight:'700',align:'center'});
},{x:gx,y:gy,scale:A.lerp(0.6,1,gIn),alpha:gIn});
if(t>kCien+0.25) A.rings(gx,gy-80,kCien+0.25,{count:2,speed:420,gap:0.15,maxR:240,color:acc,lw:4});

// FRENO 0%
if(t>kSin){
  const s=A.pop(kSin,0.45);
  A.label('FRENO 0%',890,1560,{size:44,bg:'#e8344a',color:'#fff',scale:s});
  const sp=A.p(kF,0.35,'crashIn');
  if(sp>0) A.line([[790,1590],[990,1530]],{stroke:'#fff',lw:6,progress:sp});
}

const ac=A.accent, W=A.W;
A.bg('#0a1530','#050a18');
const kT=A.k('TAG,',1.333), kCaj=A.k('cajita',2.0), kPeg=A.k('pegada',2.333), kPar=A.k('parabrisas.',3.0), kAd=A.k('Adentro',3.333), kPeq=A.k('pequeño',4.333), kTr=A.k('transmisor',4.667), kRa=A.k('radio.',5.333);
const pz=A.p(kAd,0.75,'whip');
const z=A.lerp(1,5.5,pz), Tx=A.lerp(540,680,pz), Ty=A.lerp(790,590,pz), Cx=540, Cy=800;
const S=(x,y)=>[Cx+(x-Tx)*z, Cy+(y-Ty)*z];
const sh=(t>kPeg&&t<kPeg+0.3)?10*(1-(t-kPeg)/0.3):0;
const ws=[[200,1060],[880,1060],[790,520],[290,520]];
A.with(()=>{
  // ---- mundo (parabrisas) con zoom ----
  ctx.save();
  ctx.translate(Cx,Cy); ctx.scale(z,z); ctx.translate(-Tx,-Ty);
  // carretera vista a través del vidrio
  ctx.save();
  ctx.beginPath(); ws.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.clip();
  const g=ctx.createLinearGradient(0,520,0,1060); g.addColorStop(0,'#13284f'); g.addColorStop(1,'#0b1730');
  ctx.fillStyle=g; ctx.fillRect(150,500,800,600);
  ctx.strokeStyle='rgba(255,255,255,0.25)'; ctx.lineWidth=3;
  ctx.beginPath(); ctx.moveTo(540,640); ctx.lineTo(260,1060); ctx.moveTo(540,640); ctx.lineTo(820,1060); ctx.stroke();
  for(let i=0;i<6;i++){
    const d=((t*0.9+i/6)%1), e=d*d;
    const y=A.lerp(645,1080,e), w=A.lerp(2,22,e), hh=A.lerp(4,60,e);
    ctx.fillStyle='rgba(255,255,255,'+(0.2+0.6*e)+')';
    ctx.fillRect(540-w/2,y,w,hh);
  }
  // pórtico lejano
  ctx.strokeStyle='rgba(77,208,225,0.35)'; ctx.lineWidth=3;
  ctx.strokeRect(470,600,140,40);
  ctx.restore();
  A.lib.hatch(ctx,[[200,1060],[300,1060],[340,520],[290,520]],{angle:60,spacing:18,width:1.2,color:'rgba(77,208,225,0.18)'});
  A.lib.hatch(ctx,[[880,1060],[780,1060],[740,520],[790,520]],{angle:120,spacing:18,width:1.2,color:'rgba(77,208,225,0.18)'});
  A.line([...ws,ws[0]],{stroke:'#ffffff',lw:5,progress:A.p(0,1.0,'glide')});
  // tablero
  A.line([[120,1100],[960,1100]],{stroke:ac,lw:4,alpha:0.7,progress:A.p(0.3,0.8,'glide')});
  // espejo retrovisor
  const pm=A.p(0.5,0.5,'softLand');
  A.line([[540,520],[540,555]],{stroke:'#ffffff',lw:5,alpha:pm});
  A.rect(470,555,140,48,{r:14,fill:'#1b2b4d',stroke:'#ffffff',lw:4,alpha:pm});
  ctx.restore();

  // ---- TAG en espacio de pantalla ----
  if(t>=kT){
    const drop=A.lerp(-260,0,A.p(kT,0.5,'snapSettle'));
    const [sx,sy]=S(680,590+drop);
    const pp=A.pop(kT,0.45);
    const e=t>kPeg?Math.exp(-(t-kPeg)*10):0;
    const w=64*z*pp*(1+0.25*e), h=40*z*pp*(1-0.2*e);
    const pr=A.p(kAd+0.4,0.5,'softInOut');
    // anillo "cajita"
    if(t>kCaj&&t<kAd){
      const pc=A.p(kCaj,0.4,'popOver');
      A.circle(sx,sy,70*pc,{stroke:ac,lw:4,alpha:0.9*(1-A.p(kAd-0.2,0.3))});
    }
    if(t>kPeg) A.rings(sx,sy,kPeg,{count:2,speed:420,gap:60,maxR:220,color:ac,lw:4,alpha:0.7*(1-pz)});
    A.rect(sx-w/2,sy-h/2,w,h,{r:10*z,fill:'#e8eef5',alpha:1-pr*0.88,glow:pr<0.5?ac:undefined});
    A.rect(sx-w/2,sy-h/2,w,h,{r:10*z,stroke:pr>0?ac:'#ffffff',lw:Math.max(3,1.2*z)});
    if(pr<1) A.text('TAG',sx,sy+h*0.15,{size:Math.max(16,14*z*pp),color:'#0a1530',weight:'900',align:'center',alpha:1-pr});
    // corte interior
    if(pr>0){
      const x0=sx-w/2, y0=sy-h/2;
      A.rect(x0+w*0.05,y0+h*0.08,w*0.9,h*0.84,{r:16,fill:'#0f2a3a',alpha:pr});
      for(let i=0;i<4;i++){
        const ix=w*(0.1+i*0.04), iy=h*(0.15+i*0.07);
        A.line([[x0+ix,y0+iy],[x0+w-ix,y0+iy],[x0+w-ix,y0+h-iy],[x0+ix,y0+h-iy],[x0+ix,y0+iy]],{stroke:ac,lw:5,alpha:pr,progress:A.p(kAd+0.5+i*0.12,0.6,'glide')});
      }
      // chip
      const cs=A.pop(kPeq,0.45);
      if(t>kPeq){
        const cx=sx, cy=sy, c=w*0.2*cs;
        const glow=A.p(kTr,0.3,'crashIn');
        for(let j=0;j<4;j++){
          const o=-c/2+c*(j+0.5)/4;
          A.line([[cx+o,cy-c/2-14],[cx+o,cy+c/2+14]],{stroke:'#cfd8e3',lw:4});
          A.line([[cx-c/2-14,cy+o],[cx+c/2+14,cy+o]],{stroke:'#cfd8e3',lw:4});
        }
        A.rect(cx-c/2,cy-c/2,c,c,{r:8,fill:glow>0?'#123d4a':'#1a1f2b',stroke:glow>0?ac:'#ffffff',lw:4,glow:glow>0?ac:undefined});
        if(glow>0) A.lib.glowDot(ctx,cx,cy,c*0.25*glow,{color:ac});
        if(t>kRa){
          A.rings(cx,cy,kRa,{count:4,speed:520,gap:90,maxR:520,color:ac,lw:6,alpha:0.85});
          A.flash(kRa,0.2,0.25);
        }
      }
    }
    // etiqueta TAG (antes del zoom)
    if(t>kT+0.25&&pz<1){
      const pl=A.p(kT+0.25,0.4,'softLand');
      A.label('TAG',sx+10,sy+95,{size:52,bg:ac,color:'#0a1530',scale:pl,alpha:1-pz*3});
    }
  }
  // etiqueta parabrisas
  if(t>kPar&&pz<0.4){
    const pa=A.p(kPar,0.4,'softLand'), al=1-A.clamp(pz*3);
    A.arrow(540,1390,330,1000,{progress:pa,color:'#ffffff',lw:6,alpha:al});
    A.text('PARABRISAS',540,1470,{size:76,color:'#ffffff',weight:'900',align:'center',alpha:pa*al});
  }
  if(t>kTr){
    const p1=A.p(kTr,0.4,'snapSettle');
    A.text('TRANSMISOR',540,A.lerp(1520,1460,p1),{size:92,color:ac,weight:'900',align:'center',alpha:p1});
  }
  if(t>kRa){
    const p2=A.pop(kRa,0.45);
    A.with(()=>A.text('DE RADIO',540,1590,{size:80,color:'#ffffff',weight:'900',align:'center'}),{x:540,y:1560,scale:p2});
  }
},{shake:sh});

const W=A.W, ac=A.accent;
A.bg('#06121f','#0b2236',true);
const kAnt=A.k('antena',1.333), kHab=A.k('habla,',2.667), kTag=A.k('TAG',3.667), kRes=A.k('responde',4.0), kNum=A.k('número',5.0), kId=A.k('identificación',5.667), kFr=A.k('fracción',6.667);
const roadY=1060;
// carretera
A.rect(0,roadY,W,80,{fill:'#0a1a2a'});
A.line([[0,roadY],[W,roadY]],{stroke:'#cfe8ff',lw:4});
for(let i=0;i<9;i++){const x=((i*180-t*1100)%1620+1620)%1620-180;A.rect(x,roadY+34,90,8,{fill:'#5f7f9a',r:4});}
// líneas de velocidad
for(let i=0;i<6;i++){const r=A.rand(i*7+3);const y=880+r()*150;const x=((r()*1400-t*1600)%1500+1500)%1500-300;A.line([[x,y],[x+120+r()*80,y]],{stroke:'#8fb3d1',lw:3,alpha:0.35});}
// pórtico
A.rect(940,450,34,roadY-450,{fill:'#16324a',stroke:'#cfe8ff',lw:4});
A.rect(540,450,434,38,{fill:'#16324a',stroke:'#cfe8ff',lw:4});
A.lib.hatch(ctx,[[940,488],[974,488],[974,roadY],[940,roadY]],{angle:0.8,spacing:12,width:2,color:'rgba(207,232,255,0.25)'});
// antena
const ax=720, ay=560;
const sh = t>kFr && t<kFr+0.35 ? 8 : 0;
const talk = (t>kHab-0.2 && t<kTag+0.3) ? 1 : 0;
A.with(()=>{
  A.rect(690,488,60,72,{r:8,fill:'#1d4766',stroke:'#ffffff',lw:4,glow:talk?18:0});
  A.circle(720,524,10,{fill: t>kNum+0.7? ac : '#ffffff', glow: t>kNum+0.7?20:0});
},{x:720,y:488,scale:t<kAnt?0:A.pop(kAnt),shake:sh});
if(t>kAnt) A.label('ANTENA',840,610,{size:34,bg:'#1d4766',color:'#fff',scale:A.pop(kAnt+0.1),alpha:1-A.clamp((t-kHab)/0.4)});
// auto
const cin=A.p(0,1.0,'whip');
const cx=A.lerp(-300,360,cin)+Math.max(0,t-1)*14;
const by=Math.sin(t*22)*1.5;
const body=[[cx-190,1040+by],[cx-190,975+by],[cx-120,960+by],[cx-90,895+by],[cx+60,895+by],[cx+135,960+by],[cx+195,975+by],[cx+195,1040+by]];
ctx.save();ctx.beginPath();body.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();
ctx.fillStyle='#e8eef5';ctx.fill();ctx.lineWidth=5;ctx.strokeStyle='#0a1a2a';ctx.stroke();ctx.restore();
A.lib.hatch(ctx,[[cx-190,1005+by],[cx+195,1005+by],[cx+195,1040+by],[cx-190,1040+by]],{angle:0.8,spacing:10,width:2,color:'rgba(10,26,42,0.35)'});
// ventanas
ctx.save();ctx.fillStyle='#2a5578';ctx.beginPath();ctx.moveTo(cx-100,958+by);ctx.lineTo(cx-78,907+by);ctx.lineTo(cx-10,907+by);ctx.lineTo(cx-10,958+by);ctx.closePath();ctx.fill();
ctx.beginPath();ctx.moveTo(cx+5,958+by);ctx.lineTo(cx+5,907+by);ctx.lineTo(cx+55,907+by);ctx.lineTo(cx+115,958+by);ctx.closePath();ctx.fill();ctx.restore();
for(const wx of [cx-115,cx+120]){A.circle(wx,1045,34,{fill:'#0a1a2a',stroke:'#cfe8ff',lw:4});A.circle(wx,1045,12,{fill:'#5f7f9a'});}
// TAG
const tx=cx+78, ty=925+by;
const tagS = t<kTag?1:A.lerp(1,1,0)+ (A.pop(kTag)-1)*1.5 + A.pop(kTag)*0.6;
A.with(()=>{A.rect(tx-14,ty-9,28,18,{r:4,fill:t>kTag?ac:'#9fb4c6',glow:t>kTag?22:0});},{x:tx,y:ty,scale:t<kTag?1:tagS});
if(t>kTag) A.label('TAG',tx-20,830,{size:40,bg:ac,color:'#06121f',scale:A.pop(kTag+0.05)});
// ondas
function waves(ox,oy,dx,dy,s,e,col){
  if(t<s||t>e+0.5)return;
  const fade=A.clamp((t-s)/0.2)*(1-A.clamp((t-e)/0.4));
  const dir=Math.atan2(dy-oy,dx-ox), dist=Math.hypot(dx-ox,dy-oy);
  ctx.save();ctx.strokeStyle=col;ctx.lineWidth=7;ctx.lineCap='round';ctx.shadowColor=col;ctx.shadowBlur=14;
  for(let i=0;i<4;i++){const ph=(((t-s)*1.5+i/4)%1);const r=20+ph*(dist-30);
    ctx.globalAlpha=fade*(1-ph*0.8);ctx.beginPath();ctx.arc(ox,oy,r,dir-0.35,dir+0.35);ctx.stroke();}
  ctx.restore();
}
