},{y:dy});
if(t>0.6){A.rings(540,594,0.6,{count:3,speed:260,gap:0.5,maxR:260,color:ac,lw:3,alpha:0.35});}
const cx=540,cy=830;
// ---- ENGRANAJE (cómo funciona) ----
