}
// ---- GLOBO + CHILE ----
const mundoP=A.p(kM,0.6,'snapSettle');
const qP=A.p(kQ,0.6,'glide');
const ciP=A.p(kCi,0.35,'accelExit');
const globeS=(t>=kM?A.pop(kM,0.5):0);
const groupS=A.lerp(1,0.5,qP)*(1-ciP);
const R=230;
const chilePts=[[0,-220],[16,-200],[20,-130],[28,-50],[24,30],[32,110],[40,170],[52,222],[22,216],[10,150],[-2,60],[-6,-40],[-8,-140],[-10,-212],[0,-220]];
if(groupS>0.01){
  A.with(()=>{
    if(globeS>0.01){
      A.with(()=>{
        A.circle(cx,cy,R,{fill:'#123a7a',stroke:'#ffffff',lw:5,glow:30});
        ctx.save();ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.clip();
        ctx.strokeStyle='rgba(255,255,255,0.35)';ctx.lineWidth=3;
        for(let i=0;i<4;i++){const ph=t*0.8+i*Math.PI/4;const rx=Math.abs(Math.cos(ph))*R;ctx.beginPath();ctx.ellipse(cx,cy,Math.max(rx,1),R,0,0,Math.PI*2);ctx.stroke();}
        for(let j=-2;j<=2;j++){const yy=cy+j*R*0.38;const hw=Math.sqrt(Math.max(0,R*R-(yy-cy)*(yy-cy)));ctx.beginPath();ctx.moveTo(cx-hw,yy);ctx.lineTo(cx+hw,yy);ctx.stroke();}
