      ctx.save();ctx.globalAlpha=A.clamp(chileP*1.5-0.4);ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=ac;ctx.shadowColor=ac;ctx.shadowBlur=25;ctx.fill();ctx.restore();
      A.line(pts,{stroke:'#ffffff',lw:4,progress:chileP});
